using System.Text;
using UnityEngine;
using TMPro;
using LWS.TruckBowling;
namespace LWS.TruckSports {
public enum SportsEventScreen {Setup,Play,Join,Pause,Help,Settings,Result,Confirm}
public sealed class SportsEventMenus:SportsMenuView {
 public SportsEventSession match;public SportsEventScreen Screen{get;private set;}public GameObject hud;public TMP_InputField[] names;public TMP_Text[] sources,levels,pads,colorLabels;public GameObject[] rows;public TMP_Text countText,optionText,teamAText,teamBText,setupInfo,joinInfo,header,status,standings,result,confirmText;public RectTransform[] viewPanels;public TMP_Text[] viewTexts;public GameObject[] replayButtons;
 readonly StringBuilder text=new StringBuilder(1400);bool dirty=true;float nextHUD;int returnPage;string pending;SportsMenuAction[] joinActions;SportsBroadcastScores broadcastScores;
 void Caption(TMP_Text label,string value){label.text=value;var button=label.GetComponentInParent<Michsky.UI.Heat.ButtonManager>(true);if(button!=null)button.buttonText=value;}
 public void Dirty(){dirty=true;}
 protected override void Start(){base.Start();broadcastScores=GetComponent<SportsBroadcastScores>();joinActions=pages[2].GetComponentsInChildren<SportsMenuAction>(true);for(int i=0;i<names.Length;i++){int slot=i;names[i].onEndEdit.AddListener(v=>{match.setup.players[slot].name=string.IsNullOrWhiteSpace(v)?"Player "+(slot+1):v.Trim();match.Save();});}Show(Screen);}
 public void Show(SportsEventScreen screen){Screen=screen;nextHUD=0;base.Show((int)screen);hud.SetActive(screen==SportsEventScreen.Play);if(screen==SportsEventScreen.Settings)SettingsText();dirty=true;Refresh();}
 public override void Action(string key){if(match.Running&&!match.Finished&&Screen!=SportsEventScreen.Play&&!match.MenuConfirm())return;base.Action(key);
  if(key.StartsWith("source")){match.CycleSource(int.Parse(key.Substring(6)));return;}if(key.StartsWith("level")){var p=match.setup.players[int.Parse(key.Substring(5))];p.difficulty=(BowlingDifficulty)(((int)p.difficulty+1)%3);match.Save();return;}if(key.StartsWith("pad")){int slot=int.Parse(key.Substring(3));if(match.setup.players[slot].source==BowlingSource.Keyboard)match.CycleKeyboardCluster(slot);else match.NextPad(slot);return;}if(key.StartsWith("color")){int i=int.Parse(key.Substring(5));var p=match.setup.players[i];Color.RGBToHSV(p.color,out float h,out _,out _);p.color=Color.HSVToRGB(Mathf.Repeat(h+.137f,1),.7f,1);match.Save();return;}if(key.StartsWith("reassign")){int i=int.Parse(key.Substring(8));match.RequestReplacement(i);return;}if(key.StartsWith("replay")){match.ExtraAction(key);match.ConsumeActions();return;}
  switch(key){case "count":match.setup.count=match.setup.count>=match.SetupMaximumPlayers?match.MinimumPlayers:match.setup.count+1;match.Save();break;case "teamA":match.teamA=match.teamA%4+1;match.Save();break;case "teamB":match.teamB=match.teamB%4+1;match.Save();break;case "option":match.option=(match.option+1)%match.OptionCount;match.Save();break;case "weather":match.weather=(match.weather+1)%match.WeatherCount;match.Save();break;case "allai":match.AllBots();break;case "start":case "rematch":match.StartMatch();break;case "setup":match.SetupScreen();break;case "resume":match.Resume();break;case "help":returnPage=(int)Screen;Show(SportsEventScreen.Help);break;case "settings":returnPage=(int)Screen;Show(SportsEventScreen.Settings);break;case "back":Show(Screen==SportsEventScreen.Join?SportsEventScreen.Setup:(SportsEventScreen)returnPage);break;case "front":case "restart":if(match.Running&&!match.Finished){pending=key;confirmText.text=key=="restart"?"Restart this match?\nParticipant configuration is retained.":"Return to sport selection?\nThe current match will be abandoned.";match.Gate();Show(SportsEventScreen.Confirm);}else SportsNavigation.FrontEnd();break;case "yes":if(pending=="restart")match.StartMatch();else SportsNavigation.FrontEnd();break;case "no":Show(SportsEventScreen.Pause);break;default:match.ExtraAction(key);break;}
  dirty=true;Refresh();
 }
 void Refresh(){if(!dirty)return;dirty=false;var s=match.setup;if(Screen==SportsEventScreen.Setup){Caption(countText,s.count+" COMPETITOR"+(s.count==1?"":"S"));countText.transform.parent.gameObject.SetActive(!match.TeamSport&&match.MinimumPlayers!=match.MaximumPlayers);teamAText.transform.parent.gameObject.SetActive(match.TeamSport);teamBText.transform.parent.gameObject.SetActive(match.TeamSport);Caption(teamAText,"BLUE TEAM · "+match.teamA);Caption(teamBText,"ORANGE TEAM · "+match.teamB);Caption(optionText,match.OptionLabel);for(int i=0;i<rows.Length;i++){rows[i].SetActive(i<s.count);if(i>=s.count)continue;var p=s.players[i];if(match.TeamSport)rows[i].GetComponent<RectTransform>().anchoredPosition=new Vector2(i<match.teamA?-350:350,155-(i<match.teamA?i:i-match.teamA)*108);names[i].SetTextWithoutNotify(p.name);names[i].textComponent.color=p.color;Caption(sources[i],match.ControlCaption(i));sources[i].color=Color.white;Caption(levels[i],p.source==BowlingSource.AI?p.difficulty.ToString().ToUpper():"HUMAN");levels[i].transform.parent.gameObject.SetActive(p.source==BowlingSource.AI);pads[i].transform.parent.gameObject.SetActive(p.Controller||p.source==BowlingSource.Keyboard);Caption(pads[i],p.source==BowlingSource.Keyboard?"KEYS "+match.KeyboardCluster(i):p.pad!=null&&match.Ready(i)?"PAD #"+p.pad.deviceId:"ASSIGN PAD");colorLabels[i].color=p.color;}
   match.RefreshExtraUI();setupInfo.text=match.ValidateSources(out var reason)?match.SourcePolicy:reason;Focus();}
  if(Screen==SportsEventScreen.Join){text.Clear().Append("North / Y joins the next empty assigned input source.\nReconnect the same device or explicitly reassign. Release controls before resuming.\n\n");for(int i=0;i<s.count;i++){var p=s.players[i];text.Append(p.name).Append(" · ").Append(p.source).Append(" · ").Append(match.Ready(i)?p.pad!=null?p.pad.displayName:"READY":"NOT CONNECTED").Append('\n');}if(!match.ValidateSources(out var reason))text.Append('\n').Append(reason);joinInfo.text=text.ToString();foreach(var a in joinActions){if(a.action.StartsWith("reassign")){int i=int.Parse(a.action.Substring(8));a.gameObject.SetActive(i<s.count&&s.players[i].Controller);}if(a.action=="resume")a.button.GetComponent<UnityEngine.UI.Button>().interactable=match.DevicesReady;}Focus();if(match.DevicesReady&&UnityEngine.EventSystems.EventSystem.current!=null)foreach(var a in joinActions)if(a.action=="resume"){UnityEngine.EventSystems.EventSystem.current.SetSelectedGameObject(a.gameObject);break;}}
  if(Screen==SportsEventScreen.Result)result.text=match.Results;
 }
 protected override void Update(){base.Update();Refresh();if(Screen!=SportsEventScreen.Play||Time.unscaledTime<nextHUD)return;nextHUD=Time.unscaledTime+.1f;header.transform.parent.gameObject.SetActive(!match.MultiViewHUD&&match.BroadcastHeaderVisible);status.gameObject.SetActive(!match.MultiViewHUD&&match.BroadcastStatusVisible);standings.gameObject.SetActive(match.BroadcastStandingsVisible&&!match.MultiViewHUD&&(broadcastScores==null||!broadcastScores.OwnsStandings));if(!match.MultiViewHUD){header.text=match.Header;status.text=match.Status;standings.text=match.Standings;}for(int i=0;i<viewPanels.Length;i++){bool active=i<match.cameras.Length&&match.cameras[i].enabled;viewPanels[i].gameObject.SetActive(active&&match.MultiViewHUD);if(active&&match.MultiViewHUD){var r=match.cameras[i].rect;viewPanels[i].anchorMin=r.min;viewPanels[i].anchorMax=r.max;viewPanels[i].offsetMin=viewPanels[i].offsetMax=Vector2.zero;viewTexts[i].text=match.ViewText(i);}}foreach(var b in replayButtons)b.SetActive(match.ReplayControls);}
}
}
